// Input for the email extractor: a Google Maps run's dataset (if mapsDatasetId is set) or the sheet's websites.
// requiredContact "email": only websites where an email is found are charged.
const s = $('Lead list settings').first().json;
const common = { requiredContact: 'email', dedupeStoreName: s.dedupeName, maxPagesPerSite: 5 };
const mapsId = String(s.mapsDatasetId ?? '').trim();
if (mapsId) return [{ json: { ceBody: { datasetId: mapsId, ...common } } }];
const rows = [];
for (const { json: r } of $('Read the domain sheet').all()) {
  const website = String(r[s.websiteColumn] ?? '').trim();
  if (!website) continue;
  rows.push({ row_number: r.row_number, website });
  if (rows.length >= s.maxRowsPerRun) break;
}
if (!rows.length) return [];
return [{ json: { ceBody: { rows, datasetField: 'website', rowIdField: 'row_number', ...common } } }];

// One sheet row per checked address, best first: deliverable (1), risky (2), undeliverable (3), not checked (4);
// within each, the business's best email first, then the higher score. Rows without an address are skipped.
// Company columns come from the enrichment step (one charge per company; empty when the website could not be read).
const rows = $input.all().map(({ json: r }) => r).filter((r) => String(r.email ?? '').includes('@'));
rows.sort((a, b) => (a.sendPriority ?? 4) - (b.sendPriority ?? 4)
  || Number(b.isBestEmail === true) - Number(a.isBestEmail === true)
  || (b.score ?? -1) - (a.score ?? -1));
const social = (r, k) => (r.socialProfiles ?? {})[k] ?? '';
const checkedAt = $now.toISO();
return rows.map((r) => ({ json: {
  'Email': r.email,
  'Send priority': r.sendPriority ?? 4,
  'Send status': r.sendStatus ?? 'not_checked',
  'Business': r.businessName ?? r.name ?? '',
  'Website': r.website ?? r.url ?? '',
  'Place ID': r.placeId ?? '',
  'Source row': r.rowId ?? '',
  'Best email of the business': r.isBestEmail === true ? 'yes' : 'no',
  'Score': r.score ?? '',
  'Role address': r.role ? 'yes' : 'no',
  'What the company does': r.description ?? '',
  'Industry': r.industry ?? '',
  'B2B or B2C': r.businessModel ?? '',
  'Employees': r.companySize ?? '',
  'Country': r.countryGuess ?? '',
  'Phone': r.primaryPhone ?? '',
  'LinkedIn': social(r, 'linkedin'),
  'Facebook': social(r, 'facebook'),
  'Instagram': social(r, 'instagram'),
  'Company data note': r.error ?? r.aiError ?? '',
  'Checked at': checkedAt,
} }));
